def build():
    species=[];varieties=[]
    for epithet,name,length,units,pattern,aggression,min_tank,difficulty in species_specs:
        slug='amphiprion-'+epithet;id='clown' if epithet=='ocellaris' else slug
        disputed=epithet in ['leucokranos','thiellei'];held=disputed or epithet in ['mccullochi','latezonatus','maohiensis']
        record=dict(id=id,slug=slug,name=name,scientificName='Amphiprion '+epithet,water='marine',clownfish=True,price=180 if id=='clown' else 180+round(length*10),size=9 if id=='clown' else round(length*(1.2 if units=='SL' else 1)),maxReportedLength={'cm':length,'measure':units,'source':FISHBASE},minTank=min_tank,load=12 if id=='clown' else max(12,round(length*1.5)),color='#f2a34b',pattern='clown',secondary='#f4ebd8',shape='oval',temp=[23,27] if id=='clown' else [24,26],ph=[8,8.4] if id=='clown' else [7.9,8.3],salinity=[32,36],diet=['flakes','pellets','frozen'],group=1,aggression=aggression,predator=0,activity=.8,zone=.45,habitat='rocks',life=10,maxLife=16,maturity=80,reproduction='pair',incubation=144,brood=2,breedCooldown=168,fertility=.75,rarity='Common',level=1 if min_tank<=75 else 2 if min_tank<=150 else 3,immune=.8,nocturnal=False,fictional=False,notes=f'{name}: establish a single compatible pair with rock shelter. An anemone is not required in this game.',difficulty=difficulty,taxonomyStatus='Listed by FishBase/WoRMS; hybrid origin unresolved' if disputed else 'Listed by FishBase and WoRMS',purchaseVerified=not held,careVerification='Specialist species profile incomplete; catalog-only purchase hold' if held else 'Sourced group care; species size sourced; conservative game habitat policy',realWorldLifespan=None,lifespanConfidence='No species-specific lifespan verified; simulation uses an explicit game calibration',tankDimensionsCm=[60,30,35] if min_tank<=75 else [90,40,40] if min_tank<=150 else [120,50,50],tankDimensionsStatus='Minimum game-policy footprint, not a sourced universal measurement',socialStructure='Protandrous pair; established females never revert to male',reefCompatibility='Conditional; protect coral tissue from repeated hosting contact',anemoneRequired=False,verifiedHosts=None,sourceConfidence={'taxonomy':'high; disputed origin retained' if disputed else 'high','size':'reported length, SL/TL retained','care':'group guidance with conservative game policy; specialist gaps disclosed','life':'unverified'},sources=[FISHBASE,WORMS,OATA,GUIDE],artPattern=pattern,artStatus='Provisional until anatomy/style review',approved=False,folder=f'assets/livestock/fish/clownfish/species/{slug}')
        if epithet=='maohiensis':record.update(verifiedHosts=['Heteractis magnifica'],sources=[FISHBASE,WORMS,'https://www.fishbase.se/summary/71262',OATA],careVerification='Newly described taxon; species-specific aquarium husbandry not verified')
        species.append(record)
    for index,(id,name,base,pattern,ora_slug) in enumerate(variant_specs):
        base_id='clown' if base=='ocellaris' else 'amphiprion-'+base
        provisional=id in ['mocha-storm','mocha-ocellaris','onyx-percula']
        v=dict(id=id,name=name,speciesId=base_id,scientificName='Amphiprion '+base,pattern=pattern,palette=['#f49a30','#f7f4e8','#17222c'],finModifier='longfin' if id=='longfin-ocellaris' else 'standard',phenotype={'commercialName':name,'pattern':pattern,'genotype':None,'inheritance':'Phenotype record; exact segregation is not modeled'},rarity='Rare' if index in [2,5,6,7,8,14,21,22,24] else 'Uncommon',price=260+(index%5)*30,initialStock=4 if index in [2,5,6,7,8,14,21,22,24] else 8,verificationStatus='Provisional breeder appearance; exact reference not fully verified' if provisional else 'Breeder-labelled phenotype; artwork pending user review',source=ORA if provisional else 'https://www.orafarm.com/product/'+ora_slug+'/',approved=False,sharedEarlyStages=True,folder='assets/livestock/fish/clownfish/designer/'+id)
        
        if 'mocha' in id:v['palette']=['#865838','#f6f3e8','#1b2630']
        elif id in ['black-ocellaris','black-snowflake','black-frostbite','black-storm','midnight','domino']:v['palette']=['#101822','#f6f3e8','#c77e44']
        if id in ['gladiator','davinci']:v['commercialAliasGroup']='gladiator-davinci'
        if id in ['black-ocellaris','black-snowflake','midnight','domino']:v['pattern']+=' Juvenile stage is orange-brown and only partly darkened; full jet black develops with maturity.'
        if id in ['picasso-percula','premium-picasso-percula','onyx-percula']:v['pattern']+=' Juvenile has much less black midbody pigment, which develops toward adulthood.'
        varieties.append(v)
    manifest=dict(version=1,verifiedAt='2026-10-12',species=species,varieties=varieties)
    (ROOT/'assets/livestock/fish/clownfish/collection.json').write_text(json.dumps(manifest,indent=2)+'\n',encoding='utf-8')
    script='"use strict";\nAL.ClownfishCollection='+json.dumps(manifest)+';\nAL.Clownfish={species:AL.ClownfishCollection.species,varieties:Object.fromEntries(AL.ClownfishCollection.varieties.map(v=>[v.id,v])),newSpeciesIds:AL.ClownfishCollection.species.filter(d=>d.id!=="clown").map(d=>d.id)};\nfor(const d of AL.Clownfish.species){if(d.id==="clown"){Object.assign(AL.Data.species.clown,{clownfish:true,difficulty:d.difficulty,taxonomyStatus:d.taxonomyStatus,sourceConfidence:d.sourceConfidence,careVerification:d.careVerification,sources:d.sources,purchaseVerified:true});}else AL.Data.species[d.id]=d;}\n'
    (ROOT/'js/clownfish-collection-data.js').write_text(script,encoding='utf-8')
    style='Premium Aquarium Life hybrid pixel art: crisp intentional pixel clusters, classic 16-bit readability, saturated tropical arcade colors, realistic detailed fish anatomy, carefully shaded fins, premium indie polish. Transparent alpha background. No letters, labels, frames, background, water, landscape, cast shadows or glow halos. Preserve complete fins inside isolated cells, 12 percent transparent gutter all sides. All fish face RIGHT, eye attached to head with readable dark pupil and small glint. Dead fish side-fallen right-facing, limp fins and subdued species colors, intact eyes, no gore or cross eyes. Eggs small attached amber elongated clutch, larvae translucent slender finfold and tiny residual yolk, never an adult with fully developed pattern. Juveniles individually authored developing proportions/markings. '
    for d in species:
        prompt=f"SUBJECT: {d['scientificName']} ({d['name']}). Appearance: {d['artPattern']} "+style+'Create exactly TWELVE sprites in a strict FOUR-COLUMN THREE-ROW sheet, 1536 by 1536 pixels. Row ONE from left to right: viable egg clutch, living newly hatched larva, living juvenile, living adult. Row TWO same columns: nonviable egg clutch, dead larva, dead juvenile, dead adult. Row THREE: four living ADULT swimming animation frames; identical species anatomy, body proportions, colors and markings across all four, stable head and eye; only small natural tail/fins motions differ. Use equal cell centers x192,576,960,1344 and y256,768,1280. No sprite may cross into another cell. The juvenile must differ in body development and applicable markings. Do not replace the requested species with standard ocellaris three bars unless this species calls for them.'
        folder=ROOT/d['folder'];folder.mkdir(parents=True,exist_ok=True);(folder/'GENERATION_PROMPT.md').write_text('# Built-in imagegen source prompt\n\nStatus: pending review. Species/source confidence is in collection.json.\n\n'+prompt+'\n',encoding='utf-8');d['generationPrompt']=prompt
    for v in varieties:
        prompt=f"SUBJECT: {v['name']}, designer phenotype of {v['scientificName']}. SPECIFIC MARKINGS: {v['pattern']} "+style+'Create exactly EIGHT sprites in a strict FOUR-COLUMN TWO-ROW landscape sheet, 1536 by 1024. Row ONE left to right: living developing JUVENILE, living ADULT, dead JUVENILE, dead ADULT. Row TWO: four living ADULT swimming animation frames with identical pattern/body/head registration and tiny natural fin/tail changes. No eggs or larvae here: those are shared unchanged from the underlying species. Keep every cell isolated. Correct designer markings and species eye/cheek anatomy. This is one individual phenotype sample; asymmetry is provisional, not a claim of identical natural left markings.'
        folder=ROOT/v['folder'];folder.mkdir(parents=True,exist_ok=True);(folder/'GENERATION_PROMPT.md').write_text('# Built-in imagegen designer prompt\n\nEarly stages resolve to the base species; sources/verification are in collection.json. Approval pending.\n\n'+prompt+'\n',encoding='utf-8');v['generationPrompt']=prompt
    (ROOT/'tests/clownfish-generation-jobs.json').write_text(json.dumps(species+varieties,indent=2)+'\n',encoding='utf-8')
    print('31 unique catalogued clownfish (existing Ocellaris reused), 25 designer records, 56 distinct art briefs; no freshwater data edited.')

if __name__=='__main__':build()
